#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int maxTransactions(vector<int>& transactions) {
        long long balance = 0;
        priority_queue<int, vector<int>, greater<int>> negatives;
        int postponed = 0;
        for (int value : transactions) {
            balance += value;
            if (value < 0) {
                negatives.push(value);
            }
            if (balance < 0 && !negatives.empty()) {
                balance -= negatives.top();
                negatives.pop();
                ++postponed;
            }
        }
        return static_cast<int>(transactions.size()) - postponed;
    }
};
